'use client';
import React, { useState } from 'react';

const inputStyle = { backgroundColor: '#02042d', border: '1px solid rgba(224,201,150,0.3)', color: '#ffffff', fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '15px', padding: '12px 20px', width: '100%', outline: 'none' };
const inputFocusStyle = (e: any) => e.target.style.border = '1px solid rgba(224,201,150,0.8)';
const inputBlurStyle = (e: any) => e.target.style.border = '1px solid rgba(224,201,150,0.3)';
import AnimatedHeading from './AnimatedHeading';
import { trackGenericLeadConversion, getStoredUtmParams } from '@/lib/tracking';

export default function ContactSection() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [submitError, setSubmitError] = useState(false);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitError(false);

    const target = e.target as typeof e.target & {
      name: { value: string };
      email: { value: string };
      message: { value: string };
    };

    const formData = {
      name: target.name.value,
      email: target.email.value,
      message: target.message.value,
    };

    try {
      const utm = getStoredUtmParams();
      const eventId = trackGenericLeadConversion({
        formName: 'Footer Contact Section Form',
        userEmail: formData.email,
        userName: formData.name,
        customGoogleAdsLabel: 'AW-18364005209/LYVeCM6gpMIcEN6ok4FE',
      });

      const payload = { ...formData, utm, eventId, formType: 'contact' };

      fetch('/api/send-mail', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      }).catch(() => {});

      const res = await fetch("/send-mail.php", {
        method: "POST",
        body: JSON.stringify(payload),
        headers: { "Content-Type": "application/json" },
      });

      if (res.ok) {
        setSubmitted(true);
        if (typeof window !== 'undefined' && (window as any).gtag) {
          (window as any).gtag('event', 'conversion', {
            'send_to': 'AW-18364005209/LYVeCM6gpMIcEN6ok4FE',
            'value': 0.5,
            'currency': 'AED'
          });
        }
        const formEl = e.target as HTMLFormElement;
        setTimeout(() => {
          if (typeof window !== 'undefined') {
            window.location.href = '/thank-you?type=contact';
          }
        }, 1000);
      } else {
        setSubmitError(true);
        setTimeout(() => setSubmitError(false), 4000);
      }
    } catch (err) {
      console.error("Error sending mail", err);
      setSubmitError(true);
      setTimeout(() => setSubmitError(false), 4000);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <section className="relative w-full flex items-center justify-center overflow-hidden" style={{ minHeight: '100vh', padding: 'clamp(45px, 7.5vw, 117px) clamp(24px, 5vw, 48px)' }}>
      {/* Background Image */}
      <div className="absolute inset-0 w-full h-full">
        <img
          src="/assets/images/photo-1600596542815-ffad4c1539a9.webp"
          alt="Luxury Dubai skyline and residential development background"
          fetchPriority="high"
          className="w-full h-full object-cover"
        />
        {/* Subtle overlay */}
        <div className="absolute inset-0 bg-[#02042d]/20"></div>
      </div>

      {/* Main Card (Outer padding reduced by 40%) */}
      <div className="relative z-10 w-full max-w-6xl flex flex-col md:flex-row shadow-2xl" style={{ backgroundColor: '#02042d', padding: 'clamp(24px, 3.6vw, 48px) clamp(20px, 3vw, 38px)' }}>
        {/* Left Side */}
        <div className="flex-1 md:pr-16 md:border-r border-white/10 flex flex-col justify-center">
          <div className="flex flex-col gap-4 md:gap-6">
            {/* Decreased heading size by 30% */}
            <AnimatedHeading
              text={"Your Trusted Partner in UAE Property Investment."}
              style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: 'clamp(28px, 3.15vw, 45px)', color: '#ffffff', lineHeight: 1.1, margin: 0, letterSpacing: '-1.5px' }}
            />
            <p style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: 'clamp(15px, 1.2vw, 18px)', color: 'rgba(255,255,255,0.8)', lineHeight: 1.6, margin: 0, maxWidth: '400px' }}>
              Ready to take a strategic step toward growing your real estate portfolio? Reach out to our team for honest advice, curated project recommendations and a partnership built on transparency from day one.
            </p>
          </div>
        </div>

        {/* Right Side - Form */}
        <div className="flex-1 md:pl-16 flex flex-col justify-center relative -top-2">
          <form className="flex flex-col gap-4" onSubmit={handleSubmit}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Merged First/Last Name into Name */}
              <div className="flex flex-col gap-2">
                <label className="text-white text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif' }}>Name</label>
                <input type="text" name="name" required placeholder="Ahmed Al Mansoori" className="placeholder-white/30 transition-colors" style={inputStyle} onFocus={inputFocusStyle} onBlur={inputBlurStyle} />
              </div>
              {/* Email (moved up to pair with Name) */}
              <div className="flex flex-col gap-2">
                <label className="text-white text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif' }}>Email</label>
                <input type="email" name="email" required placeholder="ahmed@gmail.com" className="placeholder-white/30 transition-colors" style={inputStyle} onFocus={inputFocusStyle} onBlur={inputBlurStyle} />
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <label className="text-white text-sm" style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif' }}>Message</label>
              {/* Further decreased textarea height */}
              <textarea name="message" required placeholder="Write your message here" style={{ height: '48px', resize: 'none', ...inputStyle }} className="placeholder-white/30 transition-colors" onFocus={inputFocusStyle} onBlur={inputBlurStyle}></textarea>
            </div>

            <button
              type="submit"
              disabled={isSubmitting || submitted}
              className={`w-full font-medium py-3 mt-2 transition-all duration-300 ease-out border ${submitError
                  ? 'bg-red-900 border-red-900 text-white'
                  : submitted
                    ? 'bg-transparent border-[#e0c996] text-[#e0c996]'
                    : 'bg-[#02042d] border-[#e0c996] text-[#e0c996] hover:bg-transparent hover:border-[#e0c996]'
                }`}
              style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '16px', borderRadius: '0px' }}
            >
              {isSubmitting ? 'Sending...' : submitError ? 'Failed to Send - Try Again' : submitted ? "✓ We'll Reach You Soon" : 'Submit'}
            </button>
          </form>
        </div>
      </div>
    </section>
  );
}