'use client';
import React, { useState } from 'react';
import Link from 'next/link';
import { BlogPost } from '@/data/blogData';

const ArrowSVGGold = () => (
  <svg viewBox="0 0 14 14" width="12" height="12" fill="none" className="arrow-icon-diagonal">
    <path d="M1 13L13 1M13 1H4M13 1V10" stroke="#e0c996" strokeWidth="1.5" strokeLinecap="square" strokeLinejoin="miter" />
  </svg>
);

const ArrowSVGDark = () => (
  <svg viewBox="0 0 14 14" width="12" height="12" fill="none" className="arrow-icon-diagonal">
    <path d="M1 13L13 1M13 1H4M13 1V10" stroke="#02042d" strokeWidth="1.5" strokeLinecap="square" strokeLinejoin="miter" />
  </svg>
);

export default function BlogCard({ post, style }: { post: BlogPost; style?: React.CSSProperties }) {
  const [hovered, setHovered] = useState(false);

  return (
    <Link
      href={`/blog/${post.slug}`}
      className="blog-card"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{
        transition: 'opacity 0.6s ease, transform 0.6s ease',
        borderRadius: '0px',
        overflow: 'hidden',
        cursor: 'pointer',
        position: 'relative',
        aspectRatio: '3/2', // 3/2 landscape ratio
        display: 'block',
        textDecoration: 'none',
        width: '100%',
        ...style
      }}
    >
      {/* Background Image */}
      <img
        src={post.image}
        alt={post.imageAlt}
        style={{
          position: 'absolute',
          inset: 0,
          width: '100%',
          height: '100%',
          objectFit: 'cover',
          transition: 'transform 0.6s ease',
          transform: hovered ? 'scale(1.05)' : 'scale(1)'
        }}
      />

      {/* Default State Info Box (White Background - Inverted) */}
      <div
        style={{
          position: 'absolute',
          bottom: '16px',
          left: '16px',
          right: '16px',
          backgroundColor: '#ffffff',
          borderRadius: '0px',
          padding: 'clamp(12px, 1.8vw, 18px) clamp(14px, 2.2vw, 20px)',
          opacity: hovered ? 0 : 1,
          transform: hovered ? 'translateY(10px)' : 'translateY(0)',
          transition: 'opacity 0.35s ease, transform 0.35s ease',
          pointerEvents: hovered ? 'none' : 'auto'
        }}
      >
        {/* Category & Time */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
          <span style={{
            border: '1px solid rgba(2, 4, 45, 0.3)',
            borderRadius: '0px',
            padding: '2px 8px',
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: '9px',
            color: '#02042d',
            textTransform: 'uppercase',
            letterSpacing: '0.05em'
          }}>
            {post.category}
          </span>
          <span style={{
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: '10px',
            color: '#555555'
          }}>
            {post.readTime}
          </span>
        </div>

        {/* Title (Line Clamped max 3 lines) */}
        <h3 style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: 'clamp(16px, 2vw, 20px)',
          fontWeight: 400,
          color: '#02042d',
          margin: '0 0 8px 0',
          lineHeight: 1.25,
          display: '-webkit-box',
          WebkitLineClamp: 3,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          textOverflow: 'ellipsis'
        }}>
          {post.title}
        </h3>

        {/* Date & Link */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '12px' }}>
          <span style={{
            fontFamily: 'Uxum Grotesque Light, sans-serif',
            fontSize: '11px',
            color: '#777777'
          }}>
            {post.publishedAt}
          </span>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#02042d' }}>
            <span style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '11px', letterSpacing: '0.05em', textTransform: 'uppercase', fontWeight: 600 }}>Read</span>
            <ArrowSVGDark />
          </div>
        </div>
      </div>

      {/* Hover State Info Box (Midnight Blue Background - Inverted) */}
      <div
        style={{
          position: 'absolute',
          bottom: '16px',
          left: '16px',
          right: '16px',
          backgroundColor: '#02042d',
          borderRadius: '0px',
          padding: 'clamp(16px, 2.5vw, 24px)',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start',
          gap: '8px',
          opacity: hovered ? 1 : 0,
          transform: hovered ? 'translateY(0)' : 'translateY(16px)',
          transition: 'opacity 0.35s ease, transform 0.35s ease',
          pointerEvents: hovered ? 'auto' : 'none'
        }}
      >
        <span style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: '10px',
          color: '#e0c996',
          fontWeight: 600,
          textTransform: 'uppercase',
          letterSpacing: '0.05em'
        }}>
          {post.category} - {post.readTime}
        </span>
        <h3 style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: 'clamp(15px, 1.8vw, 19px)',
          fontWeight: 400,
          color: '#ffffff',
          margin: 0,
          lineHeight: 1.25,
          textAlign: 'left',
          display: '-webkit-box',
          WebkitLineClamp: 3,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          textOverflow: 'ellipsis'
        }}>
          {post.title}
        </h3>
        <p style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: 'clamp(11px, 1.1vw, 12px)',
          color: 'rgba(255, 255, 255, 0.8)',
          margin: 0,
          lineHeight: 1.4,
          textAlign: 'left',
          display: '-webkit-box',
          WebkitLineClamp: 3,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          textOverflow: 'ellipsis'
        }}>
          {post.summary}
        </p>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#e0c996', marginTop: '4px' }}>
          <span style={{ fontFamily: 'Uxum Grotesque Regular, sans-serif', fontSize: '11px', letterSpacing: '0.05em', textTransform: 'uppercase', fontWeight: 600 }}>Read Article</span>
          <ArrowSVGGold />
        </div>
      </div>
    </Link>
  );
}
